#define BATCH_PRUNING_NO_MAIN
#include "batch_pruning.cpp"
#undef BATCH_PRUNING_NO_MAIN

struct ACfg{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="adaptive_batch_results.csv";int base=100000,nq=50,k=100,max_block=16;std::vector<int>probes{8,16,32,64,100};std::vector<float>gammas{1.0f,1.25f,1.5f,2.0f,3.0f,1000000.0f};};
static std::vector<float>floats(const std::string&s){std::vector<float>v;std::stringstream ss(s);std::string z;while(std::getline(ss,z,','))v.push_back(std::stof(z));return v;}
static ACfg aparse(int ac,char**av){ACfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--max-block")c.max_block=std::stoi(v());else if(a=="--nprobes")c.probes=bints(v());else if(a=="--gammas")c.gammas=floats(v());else throw std::runtime_error("unknown option "+a);}return c;}

static void select_blocks(const BTree&t,int u,int max_block,float gamma,std::vector<int>&out){const BNode&n=t.nodes[u];int count=n.end-n.begin;if(n.leaf()){out.push_back(u);return;}const BNode&l=t.nodes[n.left],&r=t.nodes[n.right];float reference=std::max({l.radius,r.radius,n.qerr,1e-5f});if(count<=max_block&&n.radius<=gamma*reference){out.push_back(u);return;}select_blocks(t,n.left,max_block,gamma,out);select_blocks(t,n.right,max_block,gamma,out);}
static BStats eval_blocks(const BTree&t,const std::vector<int>&blocks,const SQ4&sq,const float*q,float tau){BStats s;for(int u:blocks){const BNode&n=t.nodes[u];++s.nodes;s.sq_node_bytes+=108;if(qcenter_lb(q,n,sq)>tau){++s.frontier;s.pruned+=n.end-n.begin;}else{s.opened+=n.end-n.begin;for(int p=n.begin;p<n.end;++p)if(sq.lb(q,t.ids[p])<=tau)++s.exact;}}return s;}

int main(int ac,char**av)try{ACfg cfg=aparse(ac,av);Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.nq);auto ls=prefix_lists(cfg.assign,xb.rows());auto cs=centers(xb,ls);SQ4 sq(xb);std::cerr<<"Building singleton Ball Trees for radius-aware merging...\n";BatchForest forest(xb,sq,ls,1);
struct Q{std::vector<int>clusters;float tau;uint64_t visited=0,flat_exact=0;};std::vector<std::vector<Q>>qs(cfg.probes.size(),std::vector<Q>(xq.rows()));for(size_t pi=0;pi<cfg.probes.size();++pi)for(size_t qi=0;qi<xq.rows();++qi){int np=cfg.probes[pi];Q&q=qs[pi][qi];std::vector<int>pr(100);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){float x=l2(xq[qi],cs[a].data(),xb.d),y=l2(xq[qi],cs[b].data(),xb.d);return x<y||(x==y&&a<b);});q.clusters.assign(pr.begin(),pr.begin()+np);std::priority_queue<std::pair<float,int>>top;for(int c:q.clusters)for(int id:ls[c]){float d=l2(xq[qi],xb[id],xb.d);++q.visited;if((int)top.size()<cfg.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}q.tau=std::sqrt(top.top().first);for(int c:q.clusters)for(int id:ls[c])q.flat_exact+=sq.lb(xq[qi],id)<=q.tau;}
std::ofstream out(cfg.out);out<<"base,k,nprobe,max_block,gamma,avg_blocks,avg_block_size,prune_ratio,avg_opened,avg_exact,flat_bytes,adaptive_bytes,vo_reduction\n";std::cout<<"nprobe gamma avg_block prune reduction\n";
for(float gamma:cfg.gammas){std::vector<std::vector<int>>blocks(100);uint64_t total_blocks=0,total_points=0;for(int c=0;c<100;++c)if(!forest.trees[c].nodes.empty()){select_blocks(forest.trees[c],0,cfg.max_block,gamma,blocks[c]);total_blocks+=blocks[c].size();total_points+=forest.trees[c].ids.size();}std::cerr<<"gamma="<<gamma<<", global blocks="<<total_blocks<<", avg size="<<total_points/(double)total_blocks<<"\n";for(size_t pi=0;pi<cfg.probes.size();++pi){uint64_t vis=0,fexact=0,bcount=0,pruned=0,opened=0,exact=0;double nodebytes=0;for(size_t qi=0;qi<xq.rows();++qi){const Q&q=qs[pi][qi];vis+=q.visited;fexact+=q.flat_exact;for(int c:q.clusters){BStats s=eval_blocks(forest.trees[c],blocks[c],sq,xq[qi],q.tau);bcount+=s.nodes;pruned+=s.pruned;opened+=s.opened;exact+=s.exact;nodebytes+=s.sq_node_bytes;}}double nq=xq.rows(),flat=vis*72.0/nq+fexact*512.0/nq,bytes=nodebytes/nq+opened*72.0/nq+exact*512.0/nq;out<<xb.rows()<<','<<cfg.k<<','<<cfg.probes[pi]<<','<<cfg.max_block<<','<<gamma<<','<<bcount/nq<<','<<vis/(double)bcount<<','<<pruned/(double)vis<<','<<opened/nq<<','<<exact/nq<<','<<flat<<','<<bytes<<','<<1-bytes/flat<<'\n';std::cout<<std::setw(6)<<cfg.probes[pi]<<' '<<std::setw(8)<<gamma<<' '<<std::fixed<<std::setprecision(2)<<vis/(double)bcount<<' '<<std::setprecision(4)<<pruned/(double)vis<<' '<<1-bytes/flat<<'\n';}}
return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
